insert into news (author_id, camp_id, text) values
    (null, null, 'кузнец три зимы назад слышал ночью, как ангар на окраине «дышит» — с тех пор он туда не ходит даже днём'),
    (null, null, 'дочь мельника нашла в реке блестящую пластину со знаками, а староста забрал находку «на хранение» и больше не говорил о ней'),
    (null, null, 'старуха Марфа видела, как металлический столб в изгороди сам выпрямился после бури — хотя ей никто не верит, столб и правда стоит ровно'),
    (null, null, 'одна из коров пастуха повадилась ходить к старому остову на дороге и подолгу стоять там, глядя в темноту прохода'),
    (null, null, 'лекарь однажды разобрал свой «советчик», чтобы понять, как он работает — с тех пор ящик пикает на два тона тише'),
    (null, null, 'новый учитель слишком много знает про «старые вещи» для человека, пришедшего из другой деревни без единой вещи за душой'),
    (null, null, 'в прошлом году пропал охотник — ушёл к остову и не вернулся, а куда делся, никто толком не знает'),
    (null, null, 'дети видели внутри колодца огонёк, который двигался против движения ведра, хотя взрослые списывают это на игру света'),
    (null, null, 'ночью лампочки на гирлянде трактира зажглись сами, хотя праздника не было и никто их не включал'),
    (null, null, 'механический вентилятор в кузне однажды сказал одно-единственное слово, прежде чем снова замолчать навсегда'),
    (null, null, 'терминал у костра раньше умел не только рассказывать истории, но и отвечать на прямые вопросы — пока кто-то не забрал его голос'),
    (null, null, 'один из путников предлагал старосте много монет за содержимое его шкафа со «старыми вещами», а тот отказался, не сказав ни слова в ответ'),
    (null, null, 'знахарка видела точно такой же огонёк, как в колодце, глубоко в лесу — и с тех пор она туда не ходит'),
    (null, null, 'мельница однажды остановилась сама, без причины, ровно на одну ночь, а потом снова заработала, будто ничего и не было'),
    (null, null, 'кто-то нашёл в ангаре щель, через которую видно свет внутри — с тех пор дверь заколотили ещё крепче прежнего'),
    (null, null, 'до основания деревни на этом месте уже что-то было — и именно поэтому здесь так много «старых вещей»'),
    (null, null, 'молодёжь тайком пробирается к остову по ночам на спор, кто дольше просидит у входа — рекорд пока держит кузнецов подмастерье'),
    (null, null, 'раз в несколько лет из ниоткуда в деревне появляется новая работающая «старая вещь», будто кто-то оставляет её нарочно'),
    (null, null, 'дети, рождённые возле костра с терминалом, растут более любопытными к «старым вещам», чем остальные'),
    (null, null, 'тот, кто забрал голос терминала, до сих пор живёт где-то рядом с деревней и иногда наблюдает за площадью по ночам');
